"use server";

import * as z from "zod";
import { generateQuiz } from "@/ai/flows/adaptive-quiz-engine";

export const quizFormSchema = z.object({
  topic: z.string({ required_error: "Please select a topic." }),
  numQuestions: z.coerce.number().min(1).max(10),
});

export async function createQuiz(values: z.infer<typeof quizFormSchema>) {
  return await generateQuiz(values);
}
